776	//  Mirrors mamba3_oracle.layer_forward (residual OFF).
777	// ════════════════════════════════════════════════════════════════════════
778	// Mixer forward up to (but NOT including) the out_proj recombination: computes
779	// y_gated into sm->adj_a (the out_proj INPUT). Split out so the tensor-parallel
780	// path (model_stage_mamba_tc.cuh mb_forward_sample_tp) can run the replicated SSM
781	// body here and apply the ROW-parallel out_proj all-reduce itself; the SingleGPU
782	// mb_mixer_fwd below CALLS this then does the unsharded out_proj (ONE body → the
783	// SSM math is byte-identical on both paths; the pytest gate proves it).
784	__device__ inline void mb_mixer_fwd_pre_outproj(const MambaWeights::Layer& L,
785	                            const float* __restrict__ xn,   // [kSeq,d] (mixer input)
786	                            MambaSampleSmem::LayerAct* a,
787	                            MambaSampleSmem* sm) {
788	    // xz = in_proj(xn); split rows [0,d_inner)->x_in, [d_inner,2di)->z.
789	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
790	        const int s = idx / mb::kDInner, o = idx % mb::kDInner;
791	        const float* xr = xn + (int64_t)s * mb::kD;
792	        const float* Wr0 = L.in_w + (int64_t)o * mb::kD;
793	        const float* Wr1 = L.in_w + (int64_t)(mb::kDInner + o) * mb::kD;
794	        float a0 = 0.f, a1 = 0.f;
795	        #pragma unroll 4
796	        for (int k = 0; k < mb::kD; ++k) { float xv = xr[k]; a0 += xv * Wr0[k]; a1 += xv * Wr1[k]; }
797	        a->x_in[s][o] = a0;       // = x_main (NO conv, NO SiLU)
798	        a->z[s][o] = a1;
799	    }
800	    __syncthreads();
801	    // x_proj(x_in) -> sm->xproj [kSeq,xproj]; split into the SSM params.
802	    mb_linear(&a->x_in[0][0], mb::kDInner, mb::kDInner, L.x_proj_w, nullptr,
803	              mb::kXProj, &sm->xproj[0][0], mb::kXProj);
804	    // route the splits into the LayerAct caches.
805	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kXProj; idx += blockDim.x) {
806	        const int s = idx / mb::kXProj, o = idx % mb::kXProj;
807	        const float v = sm->xproj[s][o];
808	        if (o < mb::kOffAmod) a->dt_lr[s][o - mb::kOffDtLr] = v;
809	        else if (o < mb::kOffThet) a->A_mod[s][o - mb::kOffAmod] = v;
810	        else if (o < mb::kOffULam) a->theta[s][o - mb::kOffThet] = v;
811	        else if (o < mb::kOffBr) a->u_lam[s][o - mb::kOffULam] = v;
812	        else if (o < mb::kOffBi) a->Br[s][o - mb::kOffBr] = v;
813	        else if (o < mb::kOffCr) a->Bi[s][o - mb::kOffBi] = v;
814	        else if (o < mb::kOffCi) a->Cr[s][o - mb::kOffCr] = v;
815	        else a->Ci[s][o - mb::kOffCi] = v;
816	    }
817	    __syncthreads();
818	    // dt_pre = dt_proj(dt_lr) + bias  [kSeq, n_heads] (PER HEAD).
819	    mb_linear(&a->dt_lr[0][0], mb::kDtRank, mb::kDtRank, L.dt_proj_w, L.dt_proj_b,
820	              mb::kNHeads, &a->dt_pre[0][0], mb::kNHeads);
821	    // BCNorm (RMSNorm over Nc) + biases -> Bbar=(Br2,Bi2), Cbar=(Cr2,-Ci2). The
822	    //   normed output lands in sm->adj_a at WIDTH-kStateC stride (s*Nc+c), NOT the
823	    //   [kSeq][kDInner] field stride — read it back with the same Nc stride.
824	    float* an = &sm->adj_a[0][0];
825	    mb_rmsnorm_fwd(&a->Br[0][0], L.B_norm_w, an, &sm->adj_b[0][0], &a->Br_r[0], sm->red, mb::kStateC, mb::kStateC);
826	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
827	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
828	        a->Bbar[s][c][0] = an[s * mb::kStateC + c] + L.B_bias[c];
829	    }
830	    __syncthreads();
831	    mb_rmsnorm_fwd(&a->Bi[0][0], L.Bhat_norm_w, an, &sm->adj_b[0][0], &a->Bi_r[0], sm->red, mb::kStateC, mb::kStateC);
832	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
833	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
834	        a->Bbar[s][c][1] = an[s * mb::kStateC + c] + L.Bhat_bias[c];
835	    }
836	    __syncthreads();
837	    mb_rmsnorm_fwd(&a->Cr[0][0], L.C_norm_w, an, &sm->adj_b[0][0], &a->Cr_r[0], sm->red, mb::kStateC, mb::kStateC);
838	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
839	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
840	        a->Cbar[s][c][0] = an[s * mb::kStateC + c] + L.C_bias[c];
841	    }
842	    __syncthreads();
843	    mb_rmsnorm_fwd(&a->Ci[0][0], L.Chat_norm_w, an, &sm->adj_b[0][0], &a->Ci_r[0], sm->red, mb::kStateC, mb::kStateC);
844	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
845	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
846	        a->Cbar[s][c][1] = -(an[s * mb::kStateC + c] + L.Chat_bias[c]);   // Cbar imag = -(Ci2)
847	    }
848	    __syncthreads();
849	    // selective scan -> a->y_scan.
850	    mb_scan_fwd(L.A_log, a, &a->y_scan[0][0]);
851	    // y_gated = (y_scan + x_in*D) * silu(z) -> sm->adj_a (the out_proj INPUT).
852	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
853	        const int s = idx / mb::kDInner, c = idx % mb::kDInner;
854	        float yv = a->y_scan[s][c] + a->x_in[s][c] * L.D[c];
855	        sm->adj_a[s][c] = yv * mb_silu(a->z[s][c]);
856	    }
857	    __syncthreads();
858	}
