860	// Mixer forward (SingleGPU): the SSM body + the unsharded out_proj. ONE body via
861	// the _pre helper so the SSM math is shared byte-identically with the TP path.
862	__device__ inline void mb_mixer_fwd(const MambaWeights::Layer& L,
863	                            const float* __restrict__ xn,   // [kSeq,d] (mixer input)
864	                            MambaSampleSmem::LayerAct* a,
865	                            float* __restrict__ mix_out,     // [kSeq,d] OUT
866	                            MambaSampleSmem* sm) {
867	    mb_mixer_fwd_pre_outproj(L, xn, a, sm);   // → y_gated in sm->adj_a
868	    // out = out_proj(y_gated).
869	    mb_linear(&sm->adj_a[0][0], mb::kDInner, mb::kDInner, L.out_w, nullptr,
870	              mb::kD, mix_out, mb::kD);
871	}
