873	// ════════════════════════════════════════════════════════════════════════
874	//  SwiGLU forward for one sample. Input h1n = RMSNorm_mlp(h1). Caches g_pre,u_mlp.
875	//  out = down(silu(gate(x)) * up(x)). Mirrors mamba3_oracle.swiglu_forward.
876	// ════════════════════════════════════════════════════════════════════════
877	// SwiGLU forward up to (but NOT including) the down recombination: computes prod
878	// = silu(gate(x))*up(x) into sm->wff_a (the down_proj INPUT). Split out so the TP
879	// path runs gate/up (column-parallel, replicated weights here) + applies the
880	// ROW-parallel down all-reduce itself; mb_swiglu_fwd CALLS this (ONE body).
881	__device__ inline void mb_swiglu_fwd_pre_down(const MambaWeights::Layer& L,
882	                             const float* __restrict__ h1n,   // [kSeq,d]
883	                             MambaSampleSmem::LayerAct* a,
884	                             MambaSampleSmem* sm) {
885	    mb_linear(h1n, mb::kD, mb::kD, L.gate_w, nullptr, mb::kDff, &a->g_pre[0][0], mb::kDff);
886	    mb_linear(h1n, mb::kD, mb::kD, L.up_w,   nullptr, mb::kDff, &a->u_mlp[0][0], mb::kDff);
887	    // prod = silu(g_pre) * u -> sm->wff_a.
888	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDff; idx += blockDim.x) {
889	        const int s = idx / mb::kDff, o = idx % mb::kDff;
890	        sm->wff_a[s][o] = mb_silu(a->g_pre[s][o]) * a->u_mlp[s][o];
891	    }
892	    __syncthreads();
893	}
894	
895	__device__ inline void mb_swiglu_fwd(const MambaWeights::Layer& L,
896	                             const float* __restrict__ h1n,   // [kSeq,d]
897	                             MambaSampleSmem::LayerAct* a,
898	                             float* __restrict__ mlp_out,      // [kSeq,d] OUT
899	                             MambaSampleSmem* sm) {
900	    mb_swiglu_fwd_pre_down(L, h1n, a, sm);   // → prod in sm->wff_a
901	    mb_linear(&sm->wff_a[0][0], mb::kDff, mb::kDff, L.down_w, nullptr, mb::kD, mlp_out, mb::kD);
902	}
