979	// ════════════════════════════════════════════════════════════════════════
980	//  MIXER backward for one sample (CTA-cooperative, residual OFF). Given dmix_out
981	//  [kSeq,d] (= dL/d(mixer output)), accumulates the mixer's weight grads into G
982	//  and writes dxn [kSeq,d] (grad wrt the mixer INPUT = RMSNorm_mix(x)). Mirrors
983	//  mamba3_oracle.layer_backward (residual path handled by the block).
984	//  Scratch contract on entry: sm->dr holds the mixer's recomputed input xn
985	//  (re-staged by the caller). Uses adj_a/b/c, xproj, dBbar/dCbar/dtheta.
986	// ════════════════════════════════════════════════════════════════════════
987	__device__ inline void mb_mixer_bwd(const MambaWeights::Layer& L, const MambaGrad::Layer& G,
988	                            const float* __restrict__ xn,    // [kSeq,d] mixer input (recomputed)
989	                            MambaSampleSmem::LayerAct* a,
990	                            const float* __restrict__ dmix_out,  // [kSeq,d]
991	                            float* __restrict__ dxn,         // [kSeq,d] OUT
992	                            MambaSampleSmem* sm) {
993	    // Recompute y_gated -> sm->adj_a (out_proj input). y_gated = (y_scan + x_in*D)*silu(z).
994	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
995	        const int s = idx / mb::kDInner, c = idx % mb::kDInner;
996	        float yv = a->y_scan[s][c] + a->x_in[s][c] * L.D[c];
997	        sm->adj_a[s][c] = yv * mb_silu(a->z[s][c]);
998	    }
999	    __syncthreads();
1000	    // out_proj bwd: dW_out += dmix_out^T @ y_gated ; dy_gated = dmix_out @ out_w -> adj_c.
1001	    mb_linear_bwd(dmix_out, mb::kD, &sm->adj_a[0][0], mb::kDInner, L.out_w,
1002	                  mb::kDInner, mb::kD, G.out_w, nullptr, &sm->adj_c[0][0], mb::kDInner, true);
1003	    // gate+skip bwd. y_gated=y_skip*silu(z); y_skip=y_scan + x_in*D.
1004	    //   dy_skip = dy_gated*sz ; dsz = dy_gated*y_skip ; dz = dsz*silu'(z).
1005	    //   dy_scan = dy_skip ; dx_in(D-path) = dy_skip*D ; dD += Σ dy_skip*x_in.
1006	    //   dz -> sm->wff_b (NOT adj_a — the BCNorm bwd below clobbers adj_a; wff_b is
1007	    //   free in the mixer bwd and kDff>=kDInner wide). adj_b := dy_scan (scan dy).
1008	    for (int c = threadIdx.x; c < mb::kDInner; c += blockDim.x) {
1009	        float dDc = 0.0f;
1010	        #pragma unroll
1011	        for (int s = 0; s < mb::kSeq; ++s) {
1012	            float sz = mb_silu(a->z[s][c]);
1013	            float xm = a->x_in[s][c];
1014	            float yskip = a->y_scan[s][c] + xm * L.D[c];
1015	            float dyg = sm->adj_c[s][c];
1016	            float dyskip = dyg * sz;
1017	            float dsz = dyg * yskip;
1018	            sm->wff_b[s][c] = dsz * mb_silu_grad(a->z[s][c]);   // dz (survives BCNorm)
1019	            dDc += dyskip * xm;
1020	            sm->adj_b[s][c] = dyskip;          // dy_scan (D-path added back later)
1021	        }
1022	        G.D[c] += dDc;
1023	    }
1024	    __syncthreads();
1025	    // selective scan bwd. dy_scan = adj_b. Zero the head-shared reduce buffers first.
1026	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1027	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1028	        sm->dBbar[s][c][0] = 0.f; sm->dBbar[s][c][1] = 0.f;
1029	        sm->dCbar[s][c][0] = 0.f; sm->dCbar[s][c][1] = 0.f;
1030	        sm->dtheta[s][c] = 0.f;
1031	    }
1032	    __syncthreads();
1033	    // scan bwd outputs: dx_in (scan path) -> sm->wff_b rows [0,d_inner) of row 0..? No:
1034	    //   route dx_in (scan path) -> sm->adj_c[s][c] (dy_gated consumed). per-head grads
1035	    //   -> sm->wff_a (3 blocks of kSeq*n_heads); dBbar/dCbar/dtheta -> smem reduce bufs;
1036	    //   dA_log -> G.A_log (per head).
1037	    float* ddt_pre_s = &sm->wff_a[0][0];                          // [kSeq,n_heads]
1038	    float* dA_mod_s  = &sm->wff_a[0][0] + mb::kSeq * mb::kNHeads;  // [kSeq,n_heads]
1039	    float* du_lam_s  = dA_mod_s + mb::kSeq * mb::kNHeads;          // [kSeq,n_heads]
1040	    mb_scan_bwd(L.A_log, a, &sm->adj_b[0][0],
1041	                &sm->adj_c[0][0],      // dx_in (scan path) SET (dy_gated consumed)
1042	                ddt_pre_s, dA_mod_s, du_lam_s,
1043	                &sm->dBbar[0][0][0], &sm->dCbar[0][0][0], &sm->dtheta[0][0],
1044	                G.A_log, sm->red);
1045	    // dx_in total = scan-path (adj_c) + D-path (dy_skip*D, dy_skip in adj_b) -> adj_c.
1046	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDInner; idx += blockDim.x) {
1047	        const int s = idx / mb::kDInner, c = idx % mb::kDInner;
1048	        sm->adj_c[s][c] += sm->adj_b[s][c] * L.D[c];   // dx_in = scan + D path
1049	    }
1050	    __syncthreads();
1051	    // dt_proj bwd: dW_dt += ddt_pre^T @ dt_lr ; db_dt += Σ ddt_pre ;
1052	    //   ddt_lr = ddt_pre @ dt_proj_w -> staged into sm->xproj[:, kOffDtLr..dt_rank).
1053	    mb_linear_bwd(ddt_pre_s, mb::kNHeads, &a->dt_lr[0][0], mb::kDtRank, L.dt_proj_w,
1054	                  mb::kDtRank, mb::kNHeads, G.dt_proj_w, G.dt_proj_b,
1055	                  &sm->xproj[0][mb::kOffDtLr], mb::kXProj, true);
1056	    // dA_mod -> xproj[:, kOffAmod..) ; dtheta (smem) -> xproj[:, kOffThet..) ;
1057	    // du_lam -> xproj[:, kOffULam..).  (theta is a direct slice of x_proj output.)
1058	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kNHeads; idx += blockDim.x) {
1059	        const int s = idx / mb::kNHeads, hh = idx % mb::kNHeads;
1060	        sm->xproj[s][mb::kOffAmod + hh] = dA_mod_s[s * mb::kNHeads + hh];
1061	        sm->xproj[s][mb::kOffULam + hh] = du_lam_s[s * mb::kNHeads + hh];
1062	    }
1063	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1064	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1065	        sm->xproj[s][mb::kOffThet + c] = sm->dtheta[s][c];
1066	    }
1067	    __syncthreads();
1068	    // BCNorm backward for each stream. Cbar=(Cr2,-Ci2): dCr2=dCbar0, dCi2=-dCbar1.
1069	    //   Bbar=(Br2,Bi2): dBr2=dBbar0, dBi2=dBbar1. Each stream: bias grad = Σ_s d*2;
1070	    //   then RMSNorm bwd (raw pre-norm input x = a->Br/Bi/Cr/Ci, recip = *_r).
1071	    //   The staged d*2 lands in `an` at WIDTH-kStateC stride (s*Nc+c) so the
1072	    //   rmsnorm-bwd (which reads dy at that stride) + the bias reduce agree.
1073	    //   dBr -> xproj[:, kOffBr..); dBi -> kOffBi; dCr -> kOffCr; dCi -> kOffCi.
1074	    float* anb = &sm->adj_a[0][0];
1075	    // --- B real (dBr2 = dBbar0) ---
1076	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1077	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1078	        anb[s * mb::kStateC + c] = sm->dBbar[s][c][0];
1079	    }
1080	    __syncthreads();
1081	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1082	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1083	        G.B_bias[c] += acc;
1084	    }
1085	    __syncthreads();
1086	    mb_rmsnorm_bwd_rawx(anb, &a->Br[0][0], &a->Br_r[0], L.B_norm_w,
1087	                        &sm->xproj[0][mb::kOffBr], G.B_norm_w, sm->red, mb::kStateC, mb::kXProj);
1088	    __syncthreads();
1089	    // --- B imag (dBi2 = dBbar1) ---
1090	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1091	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1092	        anb[s * mb::kStateC + c] = sm->dBbar[s][c][1];
1093	    }
1094	    __syncthreads();
1095	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1096	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1097	        G.Bhat_bias[c] += acc;
1098	    }
1099	    __syncthreads();
1100	    mb_rmsnorm_bwd_rawx(anb, &a->Bi[0][0], &a->Bi_r[0], L.Bhat_norm_w,
1101	                        &sm->xproj[0][mb::kOffBi], G.Bhat_norm_w, sm->red, mb::kStateC, mb::kXProj);
1102	    __syncthreads();
1103	    // --- C real (dCr2 = dCbar0) ---
1104	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1105	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1106	        anb[s * mb::kStateC + c] = sm->dCbar[s][c][0];
1107	    }
1108	    __syncthreads();
1109	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1110	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1111	        G.C_bias[c] += acc;
1112	    }
1113	    __syncthreads();
1114	    mb_rmsnorm_bwd_rawx(anb, &a->Cr[0][0], &a->Cr_r[0], L.C_norm_w,
1115	                        &sm->xproj[0][mb::kOffCr], G.C_norm_w, sm->red, mb::kStateC, mb::kXProj);
1116	    __syncthreads();
1117	    // --- C imag (dCi2 = -dCbar1, since Cbar imag = -Ci2) ---
1118	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kStateC; idx += blockDim.x) {
1119	        const int s = idx / mb::kStateC, c = idx % mb::kStateC;
1120	        anb[s * mb::kStateC + c] = -sm->dCbar[s][c][1];
1121	    }
1122	    __syncthreads();
1123	    for (int c = threadIdx.x; c < mb::kStateC; c += blockDim.x) {
1124	        float acc = 0.f; for (int s = 0; s < mb::kSeq; ++s) acc += anb[s * mb::kStateC + c];
1125	        G.Chat_bias[c] += acc;
1126	    }
1127	    __syncthreads();
1128	    mb_rmsnorm_bwd_rawx(anb, &a->Ci[0][0], &a->Ci_r[0], L.Chat_norm_w,
1129	                        &sm->xproj[0][mb::kOffCi], G.Chat_norm_w, sm->red, mb::kStateC, mb::kXProj);
1130	    __syncthreads();
1131	    // x_proj is now fully assembled in sm->xproj (dt_lr|A_mod|theta|u_lam|Br|Bi|Cr|Ci).
1132	    //   x_proj bwd: dW_xproj += xproj^T @ x_in ; dx_in(x_proj path) = xproj @ x_proj_w
1133	    //   -> ADD to dx_in accumulator (sm->adj_c).
1134	    mb_linear_bwd(&sm->xproj[0][0], mb::kXProj, &a->x_in[0][0], mb::kDInner, L.x_proj_w,
1135	                  mb::kDInner, mb::kXProj, G.x_proj_w, nullptr, &sm->adj_c[0][0], mb::kDInner, false);
1136	    // x_in fans into THREE: scan (in adj_c via dx_acc), x_proj (just added), D-skip
1137	    //   (the D-path: dy_skip*D was added to adj_c above). All folded into adj_c now.
1138	    //   dx_in = adj_c (complete). x_in = x_main (no SiLU) -> dx_main = dx_in.
1139	    // in_proj bwd: dxz = [dx_main | dz]. dx_main = adj_c (stride kDInner) ;
1140	    //   dz = sm->wff_b (stride kDff). Build the in_proj dW + dX directly:
1141	    //   dW_in += dxz^T @ xn ; dx = dxz @ in_w -> dxn.
1142	    {
1143	        const int half = mb::kDInner;
1144	        for (int o = threadIdx.x; o < 2 * mb::kDInner; o += blockDim.x) {
1145	            const bool lo = (o < half);
1146	            const float* dyo = lo ? &sm->adj_c[0][0] : &sm->wff_b[0][0];
1147	            const int dystride = lo ? mb::kDInner : mb::kDff;
1148	            const int oo = lo ? o : (o - half);
1149	            float* gw = G.in_w + (int64_t)o * mb::kD;
1150	            for (int i = 0; i < mb::kD; ++i) {
1151	                float acc = 0.0f;
1152	                #pragma unroll
1153	                for (int s = 0; s < mb::kSeq; ++s)
1154	                    acc += dyo[s * dystride + oo] * xn[s * mb::kD + i];
1155	                gw[i] += acc;
1156	            }
1157	        }
1158	        __syncthreads();
1159	        // dxn[s,i] = Σ_{o<di} dx_main[s,o]*in_w[o,i] + Σ_{o<di} dz[s,o]*in_w[di+o,i].
1160	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1161	            const int s = idx / mb::kD, i = idx % mb::kD;
1162	            float acc = 0.0f;
1163	            for (int o = 0; o < mb::kDInner; ++o) {
1164	                acc += sm->adj_c[s][o] * L.in_w[(int64_t)o * mb::kD + i];
1165	                acc += sm->wff_b[s][o] * L.in_w[(int64_t)(mb::kDInner + o) * mb::kD + i];
1166	            }
1167	            dxn[s * mb::kD + i] = acc;
1168	        }
1169	        __syncthreads();
1170	    }
1171	}
