1173	// ════════════════════════════════════════════════════════════════════════
1174	//  SwiGLU backward for one sample. Given dmlp_out [kSeq,d], accumulates gate/up/
1175	//  down weight grads into G and writes dh1n [kSeq,d] (grad wrt mlp_norm output).
1176	//  Mirrors mamba3_oracle.swiglu_backward. Scratch: wff_a/wff_b, adj_a (d-wide).
1177	// ════════════════════════════════════════════════════════════════════════
1178	__device__ inline void mb_swiglu_bwd(const MambaWeights::Layer& L, const MambaGrad::Layer& G,
1179	                             const float* __restrict__ h1n,  // [kSeq,d] (mlp_norm out, recomputed)
1180	                             MambaSampleSmem::LayerAct* a,
1181	                             const float* __restrict__ dmlp_out,  // [kSeq,d]
1182	                             float* __restrict__ dh1n,        // [kSeq,d] OUT
1183	                             MambaSampleSmem* sm) {
1184	    // recompute prod = silu(g_pre)*u -> sm->wff_a (down_proj input).
1185	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDff; idx += blockDim.x) {
1186	        const int s = idx / mb::kDff, o = idx % mb::kDff;
1187	        sm->wff_a[s][o] = mb_silu(a->g_pre[s][o]) * a->u_mlp[s][o];
1188	    }
1189	    __syncthreads();
1190	    // down_proj bwd: dW_down += dmlp_out^T @ prod ; dprod = dmlp_out @ down_w -> wff_b.
1191	    mb_linear_bwd(dmlp_out, mb::kD, &sm->wff_a[0][0], mb::kDff, L.down_w,
1192	                  mb::kDff, mb::kD, G.down_w, nullptr, &sm->wff_b[0][0], mb::kDff, true);
1193	    // ds = dprod*u ; du = dprod*s ; dg_pre = ds*silu'(g_pre). Stage dg_pre -> wff_a,
1194	    //   du -> wff_b (dprod consumed in place).
1195	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kDff; idx += blockDim.x) {
1196	        const int s = idx / mb::kDff, o = idx % mb::kDff;
1197	        float dprod = sm->wff_b[s][o];
1198	        float sgp = mb_silu(a->g_pre[s][o]);
1199	        float ds = dprod * a->u_mlp[s][o];
1200	        float du = dprod * sgp;
1201	        sm->wff_a[s][o] = ds * mb_silu_grad(a->g_pre[s][o]);   // dg_pre
1202	        sm->wff_b[s][o] = du;                                  // du
1203	    }
1204	    __syncthreads();
1205	    // gate_proj bwd: dW_gate += dg_pre^T @ h1n ; dx_gate = dg_pre @ gate_w -> dh1n (SET).
1206	    mb_linear_bwd(&sm->wff_a[0][0], mb::kDff, h1n, mb::kD, L.gate_w,
1207	                  mb::kD, mb::kDff, G.gate_w, nullptr, dh1n, mb::kD, true);
1208	    // up_proj bwd: dW_up += du^T @ h1n ; dx_up = du @ up_w -> ADD to dh1n.
1209	    mb_linear_bwd(&sm->wff_b[0][0], mb::kDff, h1n, mb::kD, L.up_w,
1210	                  mb::kD, mb::kDff, G.up_w, nullptr, dh1n, mb::kD, false);
1211	}
