1213	// ════════════════════════════════════════════════════════════════════════
1214	//  BACKWARD for one sample (CTA-cooperative). Assumes mb_forward_sample ran for
1215	//  THIS sample. Accumulates every weight grad into the CTA partial `g`. Mirrors
1216	//  mamba3_oracle.model_backward + block_backward.
1217	// ════════════════════════════════════════════════════════════════════════
1218	__device__ inline void mb_backward_sample(const MambaWeights& w, const MambaGrad& g,
1219	                                    const int* tokens_s, int target, int B,
1220	                                    MambaSampleSmem* sm) {
1221	    // ── CE bwd: dlogits = (softmax - onehot)/B. ──
1222	    float lmax = -CUDART_INF_F;
1223	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) lmax = fmaxf(lmax, sm->logits[o]);
1224	    lmax = mb_block_max(lmax, sm->red);
1225	    float es = 0.0f;
1226	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) es += __expf(sm->logits[o] - lmax);
1227	    es = mb_block_sum(es, sm->red);
1228	    float inv_es = 1.0f / es;
1229	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
1230	        float smo = __expf(sm->logits[o] - lmax) * inv_es;
1231	        sm->logits[o] = (smo - ((o == target) ? 1.0f : 0.0f)) / (float)B;
1232	    }
1233	    __syncthreads();
1234	    // ── head: logits = hn @ out_w^T + out_b ; hn = fn_xhat[last]*norm_w (NO bias). ──
1235	    const float* xh = &sm->fn_xhat[mb::kSeq - 1][0];
1236	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
1237	        float dl = sm->logits[o];
1238	        g.out_b[o] += dl;
1239	        float* gwrow = g.out_w + (int64_t)o * mb::kD;
1240	        #pragma unroll 4
1241	        for (int j = 0; j < mb::kD; ++j) gwrow[j] += dl * (xh[j] * w.norm_w[j]);
1242	    }
1243	    __syncthreads();
1244	    // dhn[j] = Σ_o dl[o]*out_w[o,j] -> sm->dr row 0.
1245	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1246	        float acc = 0.0f;
1247	        for (int o = 0; o < mb::kPHead; ++o) acc += sm->logits[o] * w.out_w[(int64_t)o * mb::kD + j];
1248	        sm->dr[0][j] = acc;
1249	    }
1250	    __syncthreads();
1251	    // ── final RMSNorm bwd (single row last): dw += dy*xhat ; dx -> dh[last]. ──
1252	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1253	        g.norm_w[j] += sm->dr[0][j] * xh[j];
1254	    }
1255	    __syncthreads();
1256	    {
1257	        float sdax = 0.0f;
1258	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1259	            float dxhat = sm->dr[0][j] * w.norm_w[j]; sdax += dxhat * xh[j];
1260	        }
1261	        sdax = mb_block_sum(sdax, sm->red);
1262	        float corr = sdax / (float)mb::kD;
1263	        float rs = sm->fn_r[mb::kSeq - 1];
1264	        for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1265	            float dxhat = sm->dr[0][j] * w.norm_w[j];
1266	            for (int s = 0; s < mb::kSeq; ++s) sm->dh[s][j] = 0.0f;
1267	            sm->dh[mb::kSeq - 1][j] = rs * (dxhat - xh[j] * corr);
1268	        }
1269	        __syncthreads();
1270	    }
1271	    // sm->dh = dL/d(final-block output) [kSeq,d], only last pos nonzero.
1272	
1273	    for (int li = mb::kLayers - 1; li >= 0; --li) {
1274	        const MambaWeights::Layer& L = w.layer[li];
1275	        const MambaGrad::Layer& G = g.layer[li];
1276	        MambaSampleSmem::LayerAct* a = &sm->act[li];
1277	        float* hin = &sm->layer_in[li][0][0];   // block input (raw x for mixer_norm bwd)
1278	        // h2 = h1 + mlp(mlp_norm(h1)). dh2 = sm->dh.
1279	        //   dh1 = dh2 (residual) + rmsnorm_bwd(swiglu_bwd(dh2)).
1280	        // recompute h1n = mlp_norm(h1) = (h1 * mlpn_r) * mlpn_w  (xhat from the raw h1).
1281	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1282	            const int s = idx / mb::kD, j = idx % mb::kD;
1283	            sm->dr[s][j] = (a->h1[s][j] * a->mlpn_r[s]) * L.mlpn_w[j];   // h1n
1284	        }
1285	        __syncthreads();
1286	        // swiglu bwd: dmlp_out = dh2 (sm->dh) -> dh1n -> sm->fn_xhat (free: head done).
1287	        mb_swiglu_bwd(L, G, &sm->dr[0][0], a, &sm->dh[0][0], &sm->fn_xhat[0][0], sm);
1288	        // rmsnorm_mlp bwd (raw-x variant: recompute xhat from h1 * mlpn_r). dh1n in
1289	        //   sm->fn_xhat; out dh1_mlpnorm -> sm->dr (ldDx=kD).
1290	        mb_rmsnorm_bwd_rawx(&sm->fn_xhat[0][0], &a->h1[0][0], &a->mlpn_r[0], L.mlpn_w,
1291	                            &sm->dr[0][0], G.mlpn_w, sm->red, mb::kD, mb::kD);
1292	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1293	            const int s = idx / mb::kD, j = idx % mb::kD;
1294	            sm->dh[s][j] += sm->dr[s][j];   // dh1 = dh2(residual) + mlp_norm path
1295	        }
1296	        __syncthreads();
1297	        // h1 = x + mixer(mixer_norm(x)). dh1 = sm->dh.
1298	        //   dx = dh1 (residual) + rmsnorm_bwd(mixer_bwd(dh1)).
1299	        // recompute xn = mixer_norm(hin) = (hin * mixn_r) * mixn_w (xhat from raw hin).
1300	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1301	            const int s = idx / mb::kD, j = idx % mb::kD;
1302	            sm->dr[s][j] = (hin[s * mb::kD + j] * a->mixn_r[s]) * L.mixn_w[j];   // xn
1303	        }
1304	        __syncthreads();
1305	        // mixer bwd: dmix_out = dh1 (sm->dh) ; xn in sm->dr ; out dxn -> sm->fn_xhat.
1306	        mb_mixer_bwd(L, G, &sm->dr[0][0], a, &sm->dh[0][0], &sm->fn_xhat[0][0], sm);
1307	        // rmsnorm_mix bwd (raw-x variant: recompute xhat from hin * mixn_r).
1308	        mb_rmsnorm_bwd_rawx(&sm->fn_xhat[0][0], hin, &a->mixn_r[0], L.mixn_w,
1309	                            &sm->dr[0][0], G.mixn_w, sm->red, mb::kD, mb::kD);
1310	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
1311	            const int s = idx / mb::kD, j = idx % mb::kD;
1312	            sm->dh[s][j] += sm->dr[s][j];   // dx = dh1(residual) + mixer_norm path
1313	        }
1314	        __syncthreads();
1315	        // sm->dh now = grad wrt the previous block's output (or the embedding for li=0).
1316	    }
1317	
1318	    // ── embedding backward: dh = grad wrt h0 [kSeq,d]. ──
1319	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
1320	        #pragma unroll
1321	        for (int s = 0; s < mb::kSeq; ++s) {
1322	            float d = sm->dh[s][j];
1323	            g.tok[(int64_t)tokens_s[s] * mb::kD + j] += d;
1324	            g.pos[(int64_t)s * mb::kD + j] += d;
1325	        }
1326	    }
1327	    __syncthreads();
1328	}
