619	
620	    // ── P1: fwd+bwd (scalar per-sample). Fixed contiguous slice [b0,b1) for this
621	    //    CTA; the whole CTA cooperates on ONE sample at a time. ──
622	    if constexpr (!Par::kTPComm) {
623	        // ░░ DEFAULT / SingleGPU path — BYTE-IDENTICAL to the pre-Par kernel
624	        //    (batch-parallel: each CTA owns a contiguous batch slice). ░░
625	        const int base = B / nCTA, rem = B % nCTA;
626	        const int b0 = cta * base + (cta < rem ? cta : rem);
627	        const int cnt = base + (cta < rem ? 1 : 0);
628	        const int b1 = b0 + cnt;
629	        __shared__ int tok_s[mb::kSeq];
630	        __shared__ int tgt_s;
631	        float nll_acc = 0.0f;
632	        SG_MBTC_PROF_TIC(_pt);
633	        for (int b = b0; b < b1; ++b) {
634	            if (threadIdx.x < mb::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * mb::kSeq + threadIdx.x];
635	            if (threadIdx.x == 0) tgt_s = tok.targets[b];
636	            __syncthreads();
637	            float nll = mb_forward_sample(w, tok_s, tgt_s, &sm);
638	            mb_backward_sample(w, g, tok_s, tgt_s, B, &sm);
639	            if (threadIdx.x == 0) nll_acc += nll;
640	            __syncthreads();
641	        }
642	        if (threadIdx.x == 0) loss_part[cta] = nll_acc;
643	        SG_MBTC_PROF_ACC(0, _pt);
644	    } else {
645	        // ░░ kTPComm path — GRID-LOCKSTEP OVER SAMPLES so tr.rendezvous(bar) at the 4
646	        //    reduce points (mb_*_sample_tp out_proj/down fwd + in_proj/gate-up dX bwd)
647	        //    is reached the SAME number of times by every CTA on this GPU (the decoder
648	        //    tp_kernel.md §1 deadlock fix, applied to the scalar batch-parallel P1).
649	        //
650	        //    The decoder shards a TILE across the P CTA-groups; Mamba's unit of work is
651	        //    a SAMPLE (one CTA cooperatively per sample), so the analogue is: all P
652	        //    CTA-groups cooperate on the SAME sample each round, each owning the rank's
653	        //    weight-shard of the row-parallel out_proj/down. ROUND COUNT is GRID-UNIFORM
654	        //    because the activations (the batch) are REPLICATED across TP ranks (TP
655	        //    shards WEIGHTS, not the batch — decoder §1): every PE/GPU sees the SAME B
656	        //    ⇒ SAME n_rounds. A virtual PE with no sample in a round STILL calls
657	        //    tr.rendezvous(bar) (active=false, math skipped) so the arrival count is
658	        //    grid-uniform — the §1 lockstep invariant.
659	        const int P            = Par::kTP;                   // TP degree (constexpr; == tr.n_pes())
660	        const int ctas_per_pe  = nCTA / P;                   // launcher asserts nCTA % P == 0
661	        const int cta_in_pe    = ::sg::fused::sm90::tp::LoopbackTransport::cta_within_pe(cta, nCTA, P);
662	        const int64_t slot_pub = (int64_t)cta_in_pe * 2 * mbtc::mb_tp_slot_floats();
663	        const int64_t slot_red = slot_pub + mbtc::mb_tp_slot_floats();
664	        auto tr = ::sg::fused::sm90::tp::make_transport_from_comm<Par>(comm);
665	        // Samples THIS CTA's PE owns: contiguous per-PE blocks, grid-strided by
666	        // ctas_per_pe within the PE group (mirrors the batch-parallel slice but scoped
