424	// ════════════════════════════════════════════════════════════════════════
425	struct DecActs {
426	    // Per-layer linear INPUTS X (needed by dW = dY^T @ X):
427	    __nv_bfloat16* X_in[dec::kLayers];    // [T, d]    in_proj input (= layer input)
428	    __nv_bfloat16* X_ctx[dec::kLayers];   // [T, d]    out_proj input (attn context)
429	    __nv_bfloat16* X_x1[dec::kLayers];    // [T, d]    ff0 input (n1 output)
430	    __nv_bfloat16* X_gact[dec::kLayers];  // [T, dff]  ff2 input (gelu output)
431	    // Per-layer linear OUTPUT adjoints dY (needed by dW + bias db = Σ_t dY):
432	    __nv_bfloat16* dY_qkv[dec::kLayers];  // [T, 3d]   in_proj output adjoint
433	    __nv_bfloat16* dY_a[dec::kLayers];    // [T, d]    out_proj output adjoint
434	    __nv_bfloat16* dY_ff0[dec::kLayers];  // [T, dff]  ff0 output adjoint
435	    __nv_bfloat16* dY_ff2[dec::kLayers];  // [T, d]    ff2 output adjoint
436	    // Head (B rows — last position only):
437	    __nv_bfloat16* X_hn;                  // [B, d]    head input
438	    __nv_bfloat16* dY_logits;             // [B, V]    head output adjoint (dlogits)
439	    // Embedding-input adjoint (needed by tok/pos owner-scan):
440	    __nv_bfloat16* dh0;                   // [T, d]
441	};
