443	__device__ __forceinline__ DecActs dec_acts_bind(__nv_bfloat16* p, int T, int B) {
444	    DecActs a;
445	    int64_t off = 0;
446	    const int64_t Td = (int64_t)T * dec::kD;
447	    const int64_t T3d = (int64_t)T * 3 * dec::kD;
448	    const int64_t Tff = (int64_t)T * dec::kDff;
449	    for (int li = 0; li < dec::kLayers; ++li) {
450	        a.X_in[li]   = p + off; off += Td;
451	        a.X_ctx[li]  = p + off; off += Td;
452	        a.X_x1[li]   = p + off; off += Td;
453	        a.X_gact[li] = p + off; off += Tff;
454	        a.dY_qkv[li] = p + off; off += T3d;
455	        a.dY_a[li]   = p + off; off += Td;
456	        a.dY_ff0[li] = p + off; off += Tff;
457	        a.dY_ff2[li] = p + off; off += Td;
458	    }
459	    a.X_hn      = p + off; off += (int64_t)B * dec::kD;
460	    a.dY_logits = p + off; off += (int64_t)B * dec::kVocab;
461	    a.dh0       = p + off; off += Td;
462	    return a;
463	}
